logger = init_logger(__name__)

_EXPERT_SCALE_RE = re.compile(r"\.experts\.\d+\.w[123]\.scale$")

# Marker planted in the dummy hidden state returned from spec step 0 so that
# replay steps (1..K-1) are recognizable without relying on the proposer
# passing spec_step_idx. 12288 = 1.5*2^13 is exactly representable in bf16.
_REPLAY_MARKER = 12288.0

_DEBUG = os.environ.get("DS4_MTP_DEBUG", "0") == "1"
# Self-managed CUDA-graph replay of the step-0 block draft (DS4_MTP_CUDAGRAPH,
# default ON). The drafter stays eager from vLLM's point of view (the
# speculative config keeps enforce_eager, so the BreakableCUDAGraphWrapper
# around it always passes through); _forward_step0 itself captures the
# launch-bound draft computation — combine_hidden_states, insert_main_kv and
# draft_block — into a torch.cuda.CUDAGraph per (T, n_seg) decode shape and
# replays it. The host-side anchor/segment logic keeps running in Python every
# step, so the stash bookkeeping and all eager fallbacks stay live. Capture is
# only attempted for batches whose anchor layout matches the uniform decode
# pattern (n_seg segments of exactly block_size+1 rows, verified per step
# against the actual nonzero() result), after _GRAPH_WARMUP_STEPS eager
# occurrences of the shape (lets hipblaslt/triton pick algorithms and fills
# the wo_a/markov caches outside capture). Collectives inside the captured
# region (embedding + wo_b all-reduce, logits gather) record the RCCL
# fallback — the tbv_ar2 fast path refuses to run during stream capture —
# which is acceptable here: a handful of small drafter collectives.
_DS4_MTP_CUDAGRAPH = os.environ.get("DS4_MTP_CUDAGRAPH", "1") == "1"
_GRAPH_WARMUP_STEPS = 2
# DS4_MTP_FUSE_GLUE=1 (default): the rope / fp8-QAT / concat / ring-scatter
# elementwise chains in draft_block and insert_main_kv run as single fused
# triton kernels (ds4_fused_glue.dspark_*) instead of many dispatch-bound
# aten kernels each. BIT-EXACT vs the aten chains (incl. the floored-modulo
# ring semantics, edge slots, strided kv slices and the complex-mul and fp8
# round-trip rounding points); the order-dependent reductions (q headwise
# mean, attention softmax) stay in aten. These sit INSIDE the captured graph
# body. =0 restores the aten chains.
_DS4_MTP_FUSE_GLUE = os.environ.get("DS4_MTP_FUSE_GLUE", "1") == "1"
_ds4_glue = None
if _DS4_MTP_FUSE_GLUE:
    try:
        import ds4_fused_glue as _ds4_glue
    except Exception:
        _ds4_glue = None
_DS4_MTP_FUSE_GLUE = _ds4_glue is not None
# DS4_MTP_VOCAB_SHARD=1 (default): vocab-shard the markov-correction chain.
# Each TP rank keeps only its OWN vocab rows: the lm_head logits stay local
# (the in-graph logits all-gather is dropped -- those per-rank rows are
# exactly what the gather would have concatenated, so no logit changes) and
# the per-column markov GEMVs run on the rank's [V/tp, markov_rank] weight
# rows (row sharding keeps every logit ONE whole dot product on ONE rank).
# Selection becomes a distributed argmax: each rank's local argmax + the
# actual winning element value are all-gathered as (value, global_index)
# pairs and combined with NaN-as-supremum, ties -> lowest global index --
# bit-identical to torch.argmax on the full logits row (torch.argmax is
# first-occurrence-on-ties, NaN as supremum). The stash becomes the ONE-HOT
# of the drafted token (fp32 1.0 at the winner), whose argmax in the
# proposer's greedy draft sampling reproduces the selection exactly; the
# proposer contract (stash column replay, DS4_MTP_FAST_REPLAY) is unchanged.
# Applies only when the proposer can never read draft PROBABILITIES
# (draft_sample_method "probabilistic" would; checked at init) and the
# vocab splits cleanly across ranks with zero padding; anything else falls
# back to the full-logits chain. =0 restores the full chain.
_DS4_MTP_VOCAB_SHARD = os.environ.get("DS4_MTP_VOCAB_SHARD", "1") == "1"
# Position convention of the rows handed to the drafter. Observed (vLLM
# eagle/mtp proposer): input_ids are shifted left (row i carries the token
# from position i+1) but positions[i] = i = the position of the row's HIDDEN
# state. So window slot = positions[i] and the anchor token's own rope
# position is positions[anchor]+1 ("unshifted" here). "shifted" would mean
# positions track the input token instead (slot = positions[i]-1).
_POS_SHIFTED = os.environ.get("DS4_MTP_POS", "unshifted") == "shifted"


def _dspark_freqs_cis(rope_head_dim: int, max_len: int) -> torch.Tensor:
    """Reference precompute_freqs_cis with YaRN DISABLED (original_seq_len=0)
    and base theta 10000 — the drafter is pure sliding-window attention."""
    theta = 10000.0
    freqs = 1.0 / (
        theta ** (torch.arange(0, rope_head_dim, 2, dtype=torch.float32) / rope_head_dim)
    )
    t = torch.arange(max_len)
    freqs = torch.outer(t, freqs)
    return torch.polar(torch.ones_like(freqs), freqs)  # complex64 [L, rd/2]


def _apply_rope(x: torch.Tensor, freqs_cis: torch.Tensor, inverse: bool = False) -> torch.Tensor:
    """Reference apply_rotary_emb (out-of-place). x [..., rd], freqs_cis
    complex, broadcastable to x's complex view [..., rd/2]."""
    xc = torch.view_as_complex(x.float().unflatten(-1, (-1, 2)))
    if inverse:
        freqs_cis = freqs_cis.conj()
    return torch.view_as_real(xc * freqs_cis).flatten(-2).to(x.dtype)


def _act_quant_sim(x: torch.Tensor, block: int = 64) -> torch.Tensor:
    """Reference act_quant(round_scale=True, inplace=True): per-64-block fp8
    e4m3 QAT round-trip with power-of-2 (ue8m0) scale."""
    sh = x.shape
    xb = x.float().reshape(-1, block)
    amax = xb.abs().amax(-1, keepdim=True).clamp_min(1e-4)
    s = torch.exp2(torch.ceil(torch.log2(amax / 448.0)))
    y = (xb / s).clamp(-448.0, 448.0).to(torch.float8_e4m3fn).float() * s
    return y.reshape(sh).to(x.dtype)


class DSparkMarkovHead(nn.Module):
    """Additive token-transition logit bias: embed(prev_token)->markov_rank,
    then project markov_rank->vocab. Returns (logit_bias, markov_embed)."""

    def __init__(self, vocab_size: int, markov_rank: int, prefix: str = ""):
        super().__init__()
        self.markov_w1 = VocabParallelEmbedding(
            vocab_size, markov_rank, prefix=maybe_prefix(prefix, "markov_w1")
        )
        self.markov_w2 = ReplicatedLinear(
            markov_rank,
            vocab_size,
            bias=False,
            return_bias=False,
            prefix=maybe_prefix(prefix, "markov_w2"),
        )

    def forward(self, token_ids: torch.Tensor):
        embed = self.markov_w1(token_ids)
        logits = self.markov_w2(embed)
        return logits, embed


class DSparkConfidenceHead(nn.Module):
    """Per-token fp32 confidence: Linear(D + markov_rank -> 1) on
    cat([block_hidden, markov_embed])."""

    def __init__(self, input_dim: int, prefix: str = ""):
        super().__init__()
        self.proj = ReplicatedLinear(
            input_dim,
            1,
            bias=False,
            return_bias=False,
            params_dtype=torch.float32,
            prefix=maybe_prefix(prefix, "proj"),
        )

    def forward(self, hidden: torch.Tensor, markov_embed: torch.Tensor):
        x = torch.cat([hidden, markov_embed], dim=-1)
        return self.proj(x.float()).squeeze(-1)


class DSparkMultiTokenPredictorLayer(nn.Module):
    def __init__(
        self,
        vllm_config: VllmConfig,
        topk_indices_buffer: torch.Tensor,
        prefix: str,
        aux_stream_list: list[torch.cuda.Stream] | None = None,
    ) -> None:
        super().__init__()

        assert vllm_config.speculative_config is not None
        config = vllm_config.speculative_config.draft_model_config.hf_config
        self.config = config
        quant_config = vllm_config.quant_config
        self.rms_norm_eps = config.rms_norm_eps

        D = config.hidden_size
        self.hidden_size = D
        self.block_size = getattr(config, "dspark_block_size", 5)
        self.noise_token_id = getattr(config, "dspark_noise_token_id", 0)
        self.target_layer_ids = list(getattr(config, "dspark_target_layer_ids", []))
        self.markov_rank = getattr(config, "dspark_markov_rank", 256)
        n_targets = max(1, len(self.target_layer_ids))
        self.n_targets = n_targets

        # DSpark input fusion: concat(3 target-layer hiddens) -> main_proj -> main_norm.
        self.main_proj = ReplicatedLinear(
            D * n_targets,
            D,
            bias=False,
            return_bias=False,
            quant_config=quant_config,
            prefix=f"{prefix}.main_proj",
        )
        self.main_norm = RMSNorm(D, eps=config.rms_norm_eps)

        self.hc_eps = config.hc_eps
        self.hc_mult = config.hc_mult
        self.hc_dim = self.hc_mult * D
        self.hc_head_fn = nn.Parameter(
            torch.empty(self.hc_mult, self.hc_dim, dtype=torch.float32),
            requires_grad=False,
        )
        self.hc_head_base = nn.Parameter(
            torch.empty(self.hc_mult, dtype=torch.float32),
            requires_grad=False,
        )
        self.hc_head_scale = nn.Parameter(
            torch.empty(1, dtype=torch.float32),
            requires_grad=False,
        )

        # DSpark draft heads.
        self.markov_head = DSparkMarkovHead(
            config.vocab_size, self.markov_rank, prefix=f"{prefix}.markov_head"
        )
        self.confidence_head = DSparkConfidenceHead(
            D + self.markov_rank, prefix=f"{prefix}.confidence_head"
        )

        self.shared_head = SharedHead(
            config=config, prefix=prefix, quant_config=quant_config
        )
        # DSpark MTP = 3 sequential stages (checkpoint mtp.0/1/2), each a full
        # decoder block; run in ONE pass over the 5-token draft block.
        self.n_stages = int(os.environ.get("DS4_MTP_STAGES", "3"))
        # Each stage's attention needs a layer_name with exactly ONE integer
        # (vLLM parses the KV-cache layer index from it). Use distinct indices
        # num_hidden_layers + i (43,44,45) for the prefix; the nn.Module param
        # names remain ...mtp_blocks.{i}.* (used by load_weights).
        _base = config.num_hidden_layers
        self.mtp_blocks = nn.ModuleList(
            [
                DeepseekV4DecoderLayer(
                    vllm_config,
                    f"model.layers.{_base + i}",
                    topk_indices_buffer=topk_indices_buffer,
                    aux_stream_list=aux_stream_list,
                )
                for i in range(self.n_stages)
            ]
        )

        self.hc_head_op = HCHeadOp()
        self.has_tilelang = has_tilelang()

        # --- faithful DSpark drafting state -------------------------------
        attn0 = self.mtp_blocks[0].attn
        self.head_dim = attn0.head_dim            # 512 (latent kv dim)
        self.rope_head_dim = attn0.rope_head_dim  # 64
        self.q_lora_rank = attn0.q_lora_rank      # 1024
        self.window = getattr(config, "sliding_window", None) or 128
        max_len = vllm_config.model_config.max_model_len + self.block_size + 8
        self.register_buffer(
            "freqs_cis", _dspark_freqs_cis(self.rope_head_dim, max_len),
            persistent=False,
        )
        # Per-stage sliding-window cache of main_kv: [stage, seq_slot, win, kv]
        self.max_seqs = int(os.environ.get("DS4_MTP_MAXSEQS", "8"))
        self.register_buffer(
            "win_kv",
            torch.zeros(
                self.n_stages, self.max_seqs, self.window, self.head_dim,
                dtype=torch.bfloat16,
            ),
            persistent=False,
        )
        self._wo_a_cache: dict[int, torch.Tensor] = {}
        self._markov_w1_full: torch.Tensor | None = None
        # vocab-sharded markov chain (DS4_MTP_VOCAB_SHARD): lazy state,
        # {} = checked-and-disabled. The one-hot stash is only
        # selection-equivalent while the proposer argmaxes draft logits;
        # probabilistic draft sampling (or the local-argmax reduction, which
        # calls a get_top_tokens this drafter does not have) would read them
        # as a distribution, so sharding refuses to engage there.
        self._vshard_state: dict | None = None
        _spec = vllm_config.speculative_config
        self._vshard_cfg_ok = (
            _DS4_MTP_VOCAB_SHARD
            and not (
                getattr(_spec, "rejection_sample_method", "standard") == "standard"
                and getattr(_spec, "draft_sample_method", "greedy")
                == "probabilistic"
            )
            and not getattr(_spec, "use_local_argmax_reduction", False)
        )
        # stash: [Ba, block_size, vocab] markov-corrected draft logits
        self._stash_logits: torch.Tensor | None = None
        self._stash_failed = False
        self._stash_col = 0
        self._dbg_calls = 0
        # self-managed step-0 draft graphs: (T, n_seg, hidden_width) ->
        # {graph, input buffers, anchor/seq_slot constants, logits output}
        self._graph_entries: dict[tuple, dict] = {}
        self._graph_warmups: dict[tuple, int] = {}
        self._anchor_pattern_cache: dict[tuple, torch.Tensor] = {}
        self._seq_slot_pattern_cache: dict[tuple, torch.Tensor] = {}
        self._graph_disabled = False

    # ------------------------------------------------------------------
    def combine_hidden_states(self, target_hidden_states: torch.Tensor) -> torch.Tensor:
        """Project concatenated target-layer hidden (T, 3*D) -> main_x (T, D)."""
        return self.main_norm(self.main_proj(target_hidden_states))

    def _wo_a_bf16(self, stage: int) -> torch.Tensor:
        """Dequantized wo_a for the grouped low-rank o-projection einsum."""
        wb = self._wo_a_cache.get(stage)
        if wb is None:
            attn = self.mtp_blocks[stage].attn
            w = attn.wo_a.weight
            if w.dtype in (torch.float8_e4m3fn, torch.float8_e4m3fnuz):
                s = attn.wo_a.weight_scale_inv
                if s.dtype == torch.float8_e8m0fnu:
                    s = s.float()
                O, I = w.shape
                bo = O // s.shape[0]
                bi = I // s.shape[1]
                wb = (
                    w.float().view(s.shape[0], bo, s.shape[1], bi)
                    * s.float().view(s.shape[0], 1, s.shape[1], 1)
                ).view(O, I).to(torch.bfloat16)
            else:
                wb = w.to(torch.bfloat16)
            self._wo_a_cache[stage] = wb
        return wb

    def _stage_kv(self, stage: int, x: torch.Tensor) -> torch.Tensor:
        """kv_norm(wkv(x)) for a stage; x [N, D] -> [N, head_dim] (un-roped)."""
        attn = self.mtp_blocks[stage].attn
        qr_kv, _ = attn.fused_wqa_wkv(x)
        kv = qr_kv[..., self.q_lora_rank:]
        return attn.kv_norm(kv)

    def _markov_embed_weight(self) -> torch.Tensor:
        """Full (gathered) markov_w1 embedding so the markov chain needs no
        collectives — keeps TP ranks free to diverge after logits."""
        if self._markov_w1_full is None:
            w = self.markov_head.markov_w1.weight.data
            if get_tensor_model_parallel_world_size() > 1:
                from vllm.distributed import tensor_model_parallel_all_gather

                w = tensor_model_parallel_all_gather(w, dim=0)
            self._markov_w1_full = w[: self.config.vocab_size].contiguous()
        return self._markov_w1_full

    def _vocab_shard(self) -> dict | None:
        """Lazy state for the vocab-sharded markov chain (weights must be
        loaded). None = run the stock full-logits chain. The applicability
        checks are rank-symmetric, so every TP rank takes the same branch
        (collective counts must match across ranks)."""
        st = self._vshard_state
        if st is not None:
            return st or None
        ok = None
        try:
            tp = get_tensor_model_parallel_world_size()
            head = self.shared_head.head
            lp = self._lp_ref
            si = getattr(head, "shard_indices", None)
            V = self.config.vocab_size
            w2 = self.markov_head.markov_w2.weight.data
            if (
                self._vshard_cfg_ok
                and tp > 1
                and si is not None
                and V % tp == 0
                and lp is not None
                and lp.scale == 1.0
                and lp.soft_cap is None
                and not lp.logits_as_input
                and w2.shape[0] == V
            ):
                rank = get_tensor_model_parallel_rank()
                per = V // tp
                if (
                    si.org_vocab_start_index == rank * per
                    and si.org_vocab_end_index == (rank + 1) * per
                    and si.num_org_vocab_padding == 0
                    and getattr(head, "num_embeddings_per_partition", -1) == per
                ):
                    import types

                    # Own copy of this rank's markov_w2 rows: the GEMV then
                    # streams V/tp rows instead of V. Row slicing changes no
                    # dot product (each output logit is still one whole
                    # reduction over markov_rank on one rank).
                    ok = {
                        "tp": tp,
                        "per": per,
                        "start": rank * per,
                        "w2_shim": types.SimpleNamespace(
                            weight=w2[rank * per: (rank + 1) * per].contiguous()
                        ),
                    }
                    logger.info(
                        "DSpark markov chain vocab-sharded: rank %d owns rows "
                        "[%d, %d) of %d", rank, rank * per, (rank + 1) * per, V,
                    )
        except Exception:
            logger.exception(
                "DSpark vocab-shard setup failed; using the full markov chain"
            )
            ok = None
        self._vshard_state = ok if ok is not None else {}
        return ok

    def _markov_chain_sharded(
        self, hn, anchor_ids, mk_w1, vs, Ba: int, blk: int
    ) -> torch.Tensor:
        """Markov-correction chain on this rank's vocab shard with a
        distributed argmax; returns a ONE-HOT stash [Ba, blk, V] fp32 whose
        per-column argmax (the proposer's greedy draft sampling) is
        bit-identical to the full-logits chain's selection.

        Exactness argument, piece by piece:
        - local head logits: the same quant_method.apply the LogitsProcessor
          runs before its all-gather -- this rank's rows of the gathered
          tensor, bitwise, with the gather skipped.
        - bias GEMV on the rank's markov_w2 rows: bitwise equal to the same
          rows of the full GEMV (row slicing changes no dot product).
        - fp32 += bias: elementwise on identical values -> identical lanes.
        - selection: local torch.argmax (first occurrence on ties, NaN
          supreme -- same op the full chain runs, restricted to the shard)
          plus the gathered (value, global index) combine below with
          NaN-as-supremum and ties -> lowest global index reproduces
          torch.argmax over the concatenated row for every input.
        Capture-safe: device-side ops and the same recorded all-gather
        collective the logits gather used; no host syncs.
        """
        from vllm.distributed import tensor_model_parallel_all_gather

        head = self.shared_head.head
        per = vs["per"]
        local = head.quant_method.apply(head, hn, bias=None)
        local = local[..., :per].float().view(Ba, blk, per)
        onehot = local.new_zeros(Ba, blk, self.config.vocab_size)
        w2_method = self.markov_head.markov_w2.quant_method
        prev = anchor_ids
        for i in range(blk):
            emb = torch.nn.functional.embedding(prev, mk_w1)
            bias = w2_method.apply(vs["w2_shim"], emb)
            col = local[:, i]
            col += bias.float()
            li = col.argmax(dim=-1)
            lv = col.gather(-1, li.unsqueeze(-1)).squeeze(-1)
            # (value, global index) per rank; the index is exact in fp32
            # (vocab < 2^24). [Ba, 2] -> gathered [Ba, tp, 2].
            pack = torch.stack([lv, (li + vs["start"]).float()], dim=-1)
            g = tensor_model_parallel_all_gather(pack, dim=-1).view(
                Ba, vs["tp"], 2
            )
            best_v = g[:, 0, 0]
            best_i = g[:, 0, 1]
            for r in range(1, vs["tp"]):
                v = g[:, r, 0]
                gi = g[:, r, 1]
                take = (v > best_v) | (torch.isnan(v) & ~torch.isnan(best_v))
                best_v = torch.where(take, v, best_v)
                best_i = torch.where(take, gi, best_i)
            prev = best_i.long()
            onehot[:, i].scatter_(1, prev.unsqueeze(1), 1.0)
        if _DEBUG and self._dbg_calls < 40:
            self._dbg_calls += 1
            logger.info(
                "DSPARK_DBG drafts(vshard) anchor=%s chain=%s",
                anchor_ids.tolist()[:2], onehot.argmax(-1).tolist()[:2],
            )
        return onehot

    def insert_main_kv(self, main_x: torch.Tensor, slots: torch.Tensor,
                       seq_slot: torch.Tensor) -> None:
        """Insert main_kv for every row into each stage's window cache.
        main_x [N, D]; slots [N] = target position (ring index = pos % window);
        seq_slot [N] = per-request cache row. Rows must be pre-filtered to at
        most `window` per request (no duplicate ring slots)."""
        rd = self.rope_head_dim
        kvs = [self._stage_kv(s, main_x) for s in range(self.n_stages)]
        if (
            _DS4_MTP_FUSE_GLUE
            and self.n_stages == 3
            and all(k.stride(-1) == 1 and k.dtype == torch.bfloat16 for k in kvs)
            and all(k.stride(0) == kvs[0].stride(0) for k in kvs)
        ):
            # Fused rope/QAT/cat + direct ring scatter (bit-exact; see the
            # DS4_MTP_FUSE_GLUE note at the top of this file).
            _ds4_glue.dspark_insert_kv(
                kvs, self.freqs_cis, slots, seq_slot, self.win_kv, self.window
            )
            return
        fr = self.freqs_cis[slots.clamp_min(0)]
        ring = (slots % self.window).clamp_min(0)
        # Per-stage GEMMs (different weights) stay separate, but the rope /
        # fp8-QAT / concat / scatter elementwise chains are identical across
        # stages, so run them ONCE on the stacked [n_stages, N, hd] tensor.
        # Bit-exact vs the per-stage loop: the same elementwise ops applied
        # over an extra leading batch dim (fr broadcasts over stages).
        kv = torch.stack(kvs)
        roped = _apply_rope(kv[..., -rd:], fr)
        quant = _act_quant_sim(kv[..., :-rd])
        kv = torch.cat([quant, roped], dim=-1).to(torch.bfloat16)
        self.win_kv[:, seq_slot, ring] = kv

    @staticmethod
    def _win_lens(start_pos, window):
        """Window fill level per anchor, as a host list.

        One blocking D2H instead of one per (stage, anchor): start_pos is the
        same tensor for all 3 stages, so hoisting this to draft_block collapses
        3 x Ba copies into 1. Equivalent to the old
        int(min(window, int(start_pos[b].item()) + 1)) per anchor.
        """
        return torch.clamp(start_pos + 1, max=window).tolist()

    def _block_attn(self, stage: int, x: torch.Tensor, block_pos: torch.Tensor,
                    start_pos: torch.Tensor, seq_slot: torch.Tensor,
                    win_lens=None, masked: bool = False) -> torch.Tensor:
        """Faithful DSparkAttention decode: x [Ba, blk, D] post-attn_norm
        hidden; block_pos [Ba, blk] absolute positions; start_pos [Ba] anchor
        position - 1 (reference start_pos); returns [Ba, blk, D]."""
        attn = self.mtp_blocks[stage].attn
        Ba, blk, D = x.shape
        rd = self.rope_head_dim
        hd = self.head_dim
        nlh = attn.n_local_heads
        xf = x.reshape(Ba * blk, D)

        qr_kv, _ = attn.fused_wqa_wkv(xf)
        qr, kv_raw = qr_kv.split([self.q_lora_rank, hd], dim=-1)
        q = attn.wq_b(attn.q_norm(qr)).view(Ba, blk, nlh, hd)
        # headwise RMS normalization of q (reference line: q *= rsqrt(mean(q^2)))
        q = q * torch.rsqrt(q.float().square().mean(-1, keepdim=True) + attn.eps).to(q.dtype)
        fr_blk = self.freqs_cis[block_pos]  # [Ba, blk, rd/2] complex
        kv_b = attn.kv_norm(kv_raw).view(Ba, blk, hd)
        fuse = (
            _DS4_MTP_FUSE_GLUE
            and q.is_contiguous()
            and q.dtype == torch.bfloat16
            and kv_b.stride(-1) == 1
            and kv_b.dtype == torch.bfloat16
        )
        if fuse:
            # Fused rope/QAT/cat chains (bit-exact; DS4_MTP_FUSE_GLUE note).
            q = _ds4_glue.dspark_rope_cat(q, fr_blk)
            kv_b = _ds4_glue.dspark_quant_rope_cat(kv_b, fr_blk)
        else:
            q = torch.cat(
                [q[..., :-rd], _apply_rope(q[..., -rd:], fr_blk.unsqueeze(2))], dim=-1
            )
            kv_b = torch.cat(
                [_act_quant_sim(kv_b[..., :-rd]), _apply_rope(kv_b[..., -rd:], fr_blk)],
                dim=-1,
            )

        sink = attn.attn_sink[:nlh].float()  # [H]
        scale = hd ** -0.5
        if masked:
            # CUDA-graph-safe path: fixed-shape batched attention over the
            # FULL ring buffer plus the in-block keys, with ring slots at or
            # beyond the window fill level (win_len = clamp(start_pos+1,
            # window)) masked to -inf. Softmax over keys is permutation- and
            # padding-invariant, so this is semantically equivalent to the
            # variable-length slice in the eager loop below — no host-side
            # win_lens read, no data-dependent shapes, so the whole thing
            # can be stream-captured. Also batches the per-request loop.
            win = self.window
            cached = self.win_kv[stage, seq_slot]          # [Ba, win, hd]
            keys = torch.cat([cached, kv_b], dim=1).float()  # [Ba, win+blk, hd]
            scores = torch.einsum(
                "bshd,bkd->bshk", q.float(), keys
            ) * scale                                       # [Ba, blk, H, K]
            win_len = torch.clamp(start_pos + 1, max=win)   # [Ba]
            kidx = torch.arange(win + blk, device=x.device)
            invalid = (kidx.view(1, -1) < win) & (
                kidx.view(1, -1) >= win_len.view(-1, 1)
            )                                               # [Ba, win+blk]
            scores = scores.masked_fill(
                invalid.view(Ba, 1, 1, win + blk), float("-inf")
            )
            m = scores.amax(dim=-1, keepdim=True)           # [Ba, blk, H, 1]
            e = torch.exp(scores - m)
            denom = e.sum(dim=-1) + torch.exp(
                sink.view(1, 1, -1) - m.squeeze(-1)
            )                                               # [Ba, blk, H]
            o = torch.einsum("bshk,bkd->bshd", e, keys) / denom.unsqueeze(-1)
        else:
            o = torch.empty(Ba, blk, nlh, hd, dtype=torch.float32, device=x.device)
            if win_lens is None:
                win_lens = self._win_lens(start_pos, self.window)
            for b in range(Ba):
                win_len = int(win_lens[b])
                keys = torch.cat(
                    [
                        self.win_kv[stage, seq_slot[b], :win_len].to(torch.bfloat16),
                        kv_b[b],
                    ],
                    dim=0,
                )  # [K, hd]
                scores = torch.einsum(
                    "shd,kd->shk", q[b].float(), keys.float()
                ) * scale  # [blk, H, K]
                m = scores.amax(dim=-1, keepdim=True)  # [blk, H, 1]
                e = torch.exp(scores - m)
                denom = e.sum(dim=-1) + torch.exp(sink.view(1, -1) - m.squeeze(-1))
                o[b] = torch.einsum("shk,kd->shd", e, keys.float()) / denom.unsqueeze(-1)

        o = o.to(x.dtype)
        if fuse and o.is_contiguous() and o.dtype == torch.bfloat16:
            o = _ds4_glue.dspark_rope_cat(o, fr_blk, inverse=True)
        else:
            o = torch.cat(
                [o[..., :-rd], _apply_rope(o[..., -rd:], fr_blk.unsqueeze(2), inverse=True)],
                dim=-1,
            )
        # grouped low-rank o projection: wo_a einsum + wo_b (row-parallel, reduces)
        g = attn.n_local_groups
        o = o.reshape(Ba, blk, g, -1)  # heads grouped consecutively
        wo_a = self._wo_a_bf16(stage).view(g, attn.o_lora_rank, -1)
        o = torch.einsum("bsgd,grd->bsgr", o, wo_a)
        return attn.wo_b(o.flatten(2).reshape(Ba * blk, -1)).view(Ba, blk, D)

    def draft_block(self, anchor_ids: torch.Tensor, anchor_pos: torch.Tensor,
                    main_x_anchor: torch.Tensor, seq_slot: torch.Tensor,
                    embed_fn, masked: bool = False) -> torch.Tensor | None:
        """Run the full block-parallel draft for Ba anchors. Returns the
        markov-corrected logits [Ba, block_size, vocab] (None off-rank)."""
        Ba = anchor_ids.shape[0]
        blk = self.block_size
        dev = anchor_ids.device

        # NOTE: anchors' main_kv was already inserted by insert_main_kv.
        # reference start_pos (window fill level) = anchor_pos - 1 for the
        # shifted convention (anchor_pos is the anchor token's own position).
        start_pos = anchor_pos - 1 if _POS_SHIFTED else anchor_pos
        block_pos = (anchor_pos if _POS_SHIFTED else anchor_pos + 1).unsqueeze(1) \
            + torch.arange(blk, device=dev)

        draft_ids = anchor_ids.new_full((Ba, blk), self.noise_token_id)
        draft_ids[:, 0] = anchor_ids
        x = embed_fn(draft_ids.flatten())  # [Ba*blk, D]
        h = x.unsqueeze(1).repeat(1, self.hc_mult, 1)  # [Ba*blk, hc, D]

        # Hoisted out of the stage loop: start_pos does not vary by stage, so
        # this is one blocking D2H per draft instead of 3 x Ba. The masked
        # (CUDA-graph) path derives the window fill level on-device instead.
        win_lens = None if masked else self._win_lens(start_pos, self.window)

        for s, b in enumerate(self.mtp_blocks):
            residual = h
            xin, post, comb = b.hc_pre(h, b.hc_attn_fn, b.hc_attn_scale, b.hc_attn_base)
            a = b.attn_norm(xin).view(Ba, blk, -1)
            a = self._block_attn(s, a, block_pos, start_pos, seq_slot, win_lens,
                                 masked=masked)
            h = b.hc_post(a.reshape(Ba * blk, -1), residual, post, comb)
            residual = h
            xin, post, comb = b.hc_pre(h, b.hc_ffn_fn, b.hc_ffn_scale, b.hc_ffn_base)
            f = b.ffn(b.ffn_norm(xin), None)
            h = b.hc_post(f, residual, post, comb)

        # output head: hc collapse -> shared rmsnorm -> tied lm_head
        hc = self.hc_head_op(
            h.view(-1, self.hc_mult, self.hidden_size),
            self.hc_head_fn, self.hc_head_scale, self.hc_head_base,
            self.rms_norm_eps, self.hc_eps,
        )
        from vllm.models.deepseek_v4.common.ops import mtp_shared_head_rmsnorm

        hn = mtp_shared_head_rmsnorm(
            hc, self.shared_head.norm.weight.data,
            self.shared_head.norm.variance_epsilon,
        )
        mk_w1 = self._markov_embed_weight()  # gather BEFORE any rank divergence
        vs = self._vocab_shard()
        if vs is not None:
            return self._markov_chain_sharded(hn, anchor_ids, mk_w1, vs, Ba, blk)
        logits = self._lp_ref(self.shared_head.head, hn)
        if logits is None:
            return None
        V = min(logits.shape[-1], self.config.vocab_size)
        logits = logits[..., :V].float().view(Ba, blk, V)

        # autoregressive markov correction (reference forward_head), greedy
        prev = anchor_ids
        for i in range(blk):
            emb = torch.nn.functional.embedding(prev, mk_w1)
            bias = self.markov_head.markov_w2(emb)
            logits[:, i] += bias.float()[..., :V]
            prev = logits[:, i].argmax(dim=-1)
        if _DEBUG and self._dbg_calls < 40:
            self._dbg_calls += 1
            logger.info(
                "DSPARK_DBG drafts anchor=%s chain=%s",
                anchor_ids.tolist()[:2], logits.argmax(-1).tolist()[:2],
            )
        return logits

    # ------------------------------------------------------------------
    def forward(
        self,
        input_ids: torch.Tensor,
        positions: torch.Tensor,
        previous_hidden_states: torch.Tensor,
        inputs_embeds: torch.Tensor | None = None,
        spec_step_index: int = 0,
        embed_fn=None,
    ) -> torch.Tensor:
        T = previous_hidden_states.shape[0]
        # Replay step (proposer loop steps 1..K-1): hidden is our own dummy.
        #
        # spec_step_index > 0 identifies a replay without touching the tensor.
        # The marker test below reads element [0,0] back to the host, which is a
        # BLOCKING D2H that drains the queue -- and it ran on all ~5 calls per
        # decode step, step 0 included, because the shape test alone cannot
        # separate our dummy from the target's hidden (both are
        # hidden_size * n_targets wide). The sync tracer measured it at
        # 5.2 events/step, the largest remaining source after the
        # _context_lens_host memo fix.
        #
        # The proposer only supplies spec_step_index on its replay iterations
        # (token_index + 1, so always >= 1). Anything that does not supply it
        # keeps the default 0 and falls through to the original marker test, so
        # dummy_run and any other caller behave exactly as before.
        if spec_step_index > 0:
            return previous_hidden_states
        # Failsafe: never run the draft under an EXTERNAL stream capture (the
        # BreakableCUDAGraphWrapper around the drafter, enabled if the
        # speculative config ever drops enforce_eager). The marker test below
        # is a blocking D2H — hipErrorStreamCaptureUnsupported during capture
        # kills the engine at startup — and the anchor logic would bake the
        # dummy run's all-zero positions into the graph anyway.
        # The drafter manages its own graphs instead (DS4_MTP_CUDAGRAPH).
        if torch.cuda.is_current_stream_capturing():
            return previous_hidden_states
        if (
            previous_hidden_states.shape[-1] == self.hidden_size * self.n_targets
            and T > 0
            and float(previous_hidden_states[0, 0]) == _REPLAY_MARKER
        ):
            return previous_hidden_states

        try:
            return self._forward_step0(
                input_ids, positions, previous_hidden_states, embed_fn
            )
        except Exception:
            logger.exception("DSpark draft failed; serving continues at 0 acceptance")
            dummy = previous_hidden_states.new_zeros(
                T, self.hidden_size * self.n_targets
            )
            dummy[:, 0] = _REPLAY_MARKER
            self._stash_logits = None
            self._stash_failed = True
            return dummy

    def _forward_step0(self, input_ids, positions, previous_hidden_states, embed_fn):
        T = previous_hidden_states.shape[0]
        if previous_hidden_states.shape[-1] != self.hidden_size:
            main_x = self.combine_hidden_states(previous_hidden_states)
        else:
            main_x = previous_hidden_states

        pos = positions.long()
        # segment requests: a new segment starts where positions don't
        # increment by exactly 1 from the previous row.
        if T > 1:
            newseg = torch.ones(T, dtype=torch.bool, device=pos.device)
            newseg[1:] = pos[1:] != pos[:-1] + 1
        else:
            newseg = torch.ones(1, dtype=torch.bool, device=pos.device)
        seg_id = torch.cumsum(newseg.long(), dim=0) - 1  # [T]
        # Anchor rows first, then derive the segment count from them. nonzero()
        # already blocks on a data-dependent output shape, and that shape IS the
        # number of segments -- so reading seg_id[-1] back separately was a
        # second redundant stall on the same information. One blocking D2H per
        # draft instead of two.
        anchor_idx = torch.nonzero(
            torch.cat([newseg[1:], torch.ones(1, dtype=torch.bool, device=pos.device)])
        ).squeeze(-1)
        n_seg = int(anchor_idx.shape[0])
        if n_seg > self.max_seqs:
            # memory-profiling dummy run (all positions 0) or oversized batch:
            # skip drafting entirely.
            self._stash_logits = None
            self._stash_failed = True
            dummy = previous_hidden_states.new_zeros(
                T, self.hidden_size * self.n_targets
            )
            dummy[:, 0] = _REPLAY_MARKER
            return dummy
        seq_slot_rows = seg_id.clamp_max(self.max_seqs - 1)
        slots = pos - 1 if _POS_SHIFTED else pos

        if _DEBUG and self._dbg_calls < 8:
            logger.info(
                "DSPARK_DBG step0 T=%d nseg=%d pos[:6]=%s ids[:6]=%s anchors=%s "
                "anchor_pos=%s anchor_ids=%s",
                T, n_seg, pos[:6].tolist(), input_ids[:6].tolist(),
                anchor_idx.tolist()[:4], pos[anchor_idx].tolist()[:4],
                input_ids[anchor_idx].tolist()[:4],
            )
            self._dbg_calls += 1

        # CUDA-graph replay of the whole draft for uniform decode batches:
        # n_seg segments of exactly T/n_seg rows each. T here is the number
        # of ACCEPTED rows (disable_padded_drafter_batch), so it varies step
        # to step between n_seg and n_seg*(block_size+1) — for a single
        # sequence (n_seg=1, the dominant interactive case) every layout is
        # trivially uniform and every decode step replays one of at most
        # block_size+1 tiny graphs. Multi-sequence steps replay only when the
        # sequences happened to accept equally; the T cap keeps prefill
        # chunks (whose lengths would mint a graph per prompt) eager. The
        # anchor layout is verified against the actual data every step;
        # anything else falls through to the eager path below unchanged.
        # The attn_metadata probe restricts capture/replay to REAL engine
        # steps: every dummy run (memory profiling, warmup, the runner's own
        # cudagraph capture phase) passes attn_metadata=None, has all-zero
        # positions that masquerade as legitimate q=1 layouts, and crashes
        # the boot if a graph capture lands in the middle of it.
        if (
            _DS4_MTP_CUDAGRAPH
            and not _DEBUG
            and not self._graph_disabled
            and T <= self.window
            and T % n_seg == 0
            and T <= n_seg * (self.block_size + 1)
            and is_forward_context_available()
            and get_forward_context().attn_metadata is not None
        ):
            handled, logits = self._draft_via_graph(
                previous_hidden_states, input_ids, pos, anchor_idx,
                T, n_seg, embed_fn,
            )
            if handled:
                self._stash_logits = logits
                self._stash_failed = False
                self._stash_col = 0
                dummy = previous_hidden_states.new_zeros(
                    T, self.hidden_size * self.n_targets
                )
                dummy[:, 0] = _REPLAY_MARKER
                return dummy

        # Only the last `window` rows per segment can land in the ring buffer;
        # dropping earlier rows avoids duplicate ring-slot scatter (undefined
        # winner) and bounds prefill insertion cost.
        # A segment's rows are consecutive positions, so a segment of length L
        # keeps every row iff L <= window, and T bounds every segment length.
        # T <= window is therefore a sufficient HOST-side test for "keep is all
        # True" -- at decode T = 1 + num_spec = 6 against window 128, so it always
        # holds. Each of the three boolean-mask index ops below runs its own
        # nonzero(), and a data-dependent output size forces a blocking D2H, so
        # this removes 3 syncs per step. The masked path stays for prefill.
        if T <= self.window:
            self.insert_main_kv(main_x, slots, seq_slot_rows)
        else:
            seg_max = slots[anchor_idx][seg_id]  # per-row max slot of its segment
            keep = slots > seg_max - self.window
            self.insert_main_kv(
                main_x[keep], slots[keep], seq_slot_rows[keep]
            )

        logits = self.draft_block(
            input_ids[anchor_idx],
            pos[anchor_idx],
            main_x[anchor_idx],
            seq_slot_rows[anchor_idx],
            embed_fn,
        )
        self._stash_logits = logits
        self._stash_failed = False
        self._stash_col = 0

        dummy = previous_hidden_states.new_zeros(T, self.hidden_size * self.n_targets)
        dummy[:, 0] = _REPLAY_MARKER
        return dummy

    # --- self-managed CUDA-graph capture of the step-0 draft ---------------

    def _anchor_pattern(self, T: int, n_seg: int, dev) -> torch.Tensor:
        """Anchor rows of a uniform batch: last row of each q-row segment.
        Cached per shape — the tensor is baked into captured graphs as a
        gather index, so it must stay alive and address-stable."""
        pat = self._anchor_pattern_cache.get((T, n_seg))
        if pat is None:
            q = T // n_seg
            pat = torch.arange(q - 1, T, q, device=dev)
            self._anchor_pattern_cache[(T, n_seg)] = pat
        return pat

    def _seq_slot_pattern(self, T: int, n_seg: int, dev) -> torch.Tensor:
        """Per-row cache slot of a uniform batch (row // q); cached alongside
        the anchor pattern for the same address-stability reason."""
        pat = self._seq_slot_pattern_cache.get((T, n_seg))
        if pat is None:
            q = T // n_seg
            pat = (torch.arange(T, device=dev) // q).clamp_max(
                self.max_seqs - 1
            )
            self._seq_slot_pattern_cache[(T, n_seg)] = pat
        return pat

    def _draft_via_graph(
        self, prev_hidden, input_ids, pos, anchor_idx, T, n_seg, embed_fn
    ):
        """Replay (capturing on first use after warmup) the step-0 draft for a
        uniform decode batch. Returns (handled, stash logits). handled=False
        means the caller must run the eager path (warmup, layout mismatch, or
        capture permanently disabled after a failure)."""
        expected = self._anchor_pattern(T, n_seg, pos.device)
        # One blocking D2H per step (replaces the eager path's _win_lens
        # read): the graph's baked anchor layout must match the actual data.
        if not bool(torch.equal(anchor_idx, expected)):
            return False, None
        key = (T, n_seg, int(prev_hidden.shape[-1]))
        entry = self._graph_entries.get(key)
        if entry is None:
            warm = self._graph_warmups.get(key, 0) + 1
            self._graph_warmups[key] = warm
            if warm <= _GRAPH_WARMUP_STEPS:
                # Warm up by running the EXACT graph body eagerly (not the
                # stock loop path): every kernel and hipblaslt GEMM shape the
                # capture will record must have run at least once first —
                # hipblaslt's algo-selection miss path makes HIP calls that
                # are illegal during stream capture and crash the worker
                # ('operation not permitted when stream is capturing').
                seq_slot_c = self._seq_slot_pattern(T, n_seg, pos.device)
                logits = self._graph_draft_body(
                    input_ids, pos, prev_hidden, expected, seq_slot_c, embed_fn
                )
                return True, logits
            try:
                entry = self._capture_draft_graph(
                    key, prev_hidden, input_ids, pos, expected, embed_fn
                )
            except Exception:
                logger.exception(
                    "DSpark step-0 draft graph capture failed; the drafter "
                    "stays fully eager for the rest of this process"
                )
                self._graph_disabled = True
                return False, None
            self._graph_entries[key] = entry
        entry["hidden"].copy_(prev_hidden)
        entry["ids"].copy_(input_ids)
        entry["pos"].copy_(pos)
        entry["graph"].replay()
        return True, entry["logits"]

    def _capture_draft_graph(
        self, key, prev_hidden, input_ids, pos, anchor_c, embed_fn
    ) -> dict:
        """Capture combine -> insert_main_kv -> draft_block for one decode
        shape into a CUDAGraph reading from private static input buffers.
        Kernels do not execute during capture; the caller replays immediately
        after, so the capturing step still produces a real draft."""
        T, n_seg, _ = key
        dev = prev_hidden.device
        bufs = {
            "hidden": torch.empty_like(prev_hidden),
            "ids": torch.empty_like(input_ids),
            "pos": torch.empty_like(pos),
        }
        bufs["hidden"].copy_(prev_hidden)
        bufs["ids"].copy_(input_ids)
        bufs["pos"].copy_(pos)
        # Uniform layout makes seq_slot a shape constant (row // q); like the
        # anchor pattern it is baked into the graph, so keep a reference.
        seq_slot_c = self._seq_slot_pattern(T, n_seg, dev)
        graph = torch.cuda.CUDAGraph()
        torch.cuda.synchronize()
        with torch.cuda.graph(
            graph, pool=current_platform.get_global_graph_pool()
        ):
            logits = self._graph_draft_body(
                bufs["ids"], bufs["pos"], bufs["hidden"],
                anchor_c, seq_slot_c, embed_fn,
            )
        logger.info(
            "DSpark step-0 draft cudagraph captured (T=%d, n_seg=%d)", T, n_seg
        )
        return {
            "graph": graph, "logits": logits, "seq_slot": seq_slot_c, **bufs
        }

    def _graph_draft_body(
        self, ids, pos, prev_hidden, anchor_idx, seq_slot_rows, embed_fn
    ):
        """The captured region: device-only mirror of the eager step-0 path
        for a uniform decode batch (T <= window, precomputed anchors)."""
        if prev_hidden.shape[-1] != self.hidden_size:
            main_x = self.combine_hidden_states(prev_hidden)
        else:
            main_x = prev_hidden
        slots = pos - 1 if _POS_SHIFTED else pos
        self.insert_main_kv(main_x, slots, seq_slot_rows)
        return self.draft_block(
            ids[anchor_idx],
            pos[anchor_idx],
            main_x[anchor_idx],
            seq_slot_rows[anchor_idx],
            embed_fn,
            masked=True,
        )

    def stashed_logits(self) -> torch.Tensor | None:
        if self._stash_logits is None:
            return None
        col = min(self._stash_col, self._stash_logits.shape[1] - 1)
        self._stash_col += 1
        return self._stash_logits[:, col].contiguous()


class DSparkMultiTokenPredictor(nn.Module):
    def __init__(self, *, vllm_config: VllmConfig, prefix: str = ""):
        super().__init__()
        config = vllm_config.model_config.hf_config
        self.mtp_start_layer_idx = config.num_hidden_layers
        self.num_mtp_layers = config.num_nextn_predict_layers
        self.device = current_platform.device_type

        topk_tokens = config.index_topk
        self.topk_indices_buffer = torch.empty(
            vllm_config.scheduler_config.max_num_batched_tokens,
            topk_tokens,
            dtype=torch.int32,
            device=self.device,
        )

        aux_stream_list = (
            None
            if current_platform.is_rocm()
            else [torch.cuda.Stream() for _ in range(3)]
        )

        self.layers = torch.nn.ModuleDict(
            {
                str(idx): DSparkMultiTokenPredictorLayer(
                    vllm_config,
                    self.topk_indices_buffer,
                    f"{prefix}.layers.{idx}",
                    aux_stream_list=aux_stream_list,
                )
                for idx in range(
                    self.mtp_start_layer_idx,
                    self.mtp_start_layer_idx + self.num_mtp_layers,
                )
            }
        )
        self.embed_tokens = VocabParallelEmbedding(
            config.vocab_size,
            config.hidden_size,
            prefix=maybe_prefix(prefix, "embed_tokens"),
        )
        self.logits_processor = LogitsProcessor(config.vocab_size)
        for layer in self.layers.values():
            # plain attribute (bypass nn.Module registration; avoids the
            # class-attr-shadows-__getattr__ None trap)
            object.__setattr__(layer, "_lp_ref", self.logits_processor)

    def embed_input_ids(self, input_ids: torch.Tensor) -> torch.Tensor:
        return self.embed_tokens(input_ids)

    def _layer(self, spec_step_idx: int = 0) -> DSparkMultiTokenPredictorLayer:
        return self.layers[str(self.mtp_start_layer_idx)]

    def forward(
        self,
        input_ids: torch.Tensor,
        positions: torch.Tensor,
        previous_hidden_states: torch.Tensor,
        inputs_embeds: torch.Tensor | None = None,
        spec_step_idx: int = 0,
    ) -> torch.Tensor:
        return self._layer()(
            input_ids,
            positions,
            previous_hidden_states,
            inputs_embeds,
            spec_step_idx,
            embed_fn=self.embed_tokens,
        )

    def combine_hidden_states(self, target_hidden_states: torch.Tensor) -> torch.Tensor:
        return self._layer().combine_hidden_states(target_hidden_states)

    def compute_logits(
        self,
        hidden_states: torch.Tensor,
        spec_step_idx: int = 0,
    ) -> torch.Tensor | None:
        """Replay the stashed markov-corrected draft logits, one block column
        per proposer step. Falls back to zeros if no stash (draft failed)."""
        layer = self._layer()
        out = layer.stashed_logits()
        if out is None:
            if layer._stash_failed:
                # draft crashed: benign zeros (rejection sampler discards)
                return hidden_states.new_zeros(
                    hidden_states.shape[0], layer.config.vocab_size,
                    dtype=torch.float32,
                )
            return None
        n = hidden_states.shape[0]
        if out.shape[0] != n:
            if _DEBUG:
                logger.warning(
                    "DSPARK_DBG stash rows %d != sample rows %d", out.shape[0], n
                )
            fixed = out.new_zeros(n, out.shape[-1])
            fixed[: min(n, out.shape[0])] = out[: min(n, out.shape[0])]
            out = fixed
        return out


class DSparkMTP(nn.Module):
    # Contract used by the proposer's DS4_MTP_FAST_REPLAY path: replay
    # iterations (spec_step_idx >= 1) return immediately from forward()
    # without reading input_ids/positions/hidden values, slot mappings or
    # attention metadata, and compute_logits() replays stashed columns; the
    # proposer may therefore skip rebuilding those inputs on replay steps.
    dspark_replay_ignores_inputs = True

    def __init__(self, *, vllm_config: VllmConfig, prefix: str = ""):
        super().__init__()
        self.config = vllm_config.model_config.hf_config
        self.quant_config = vllm_config.quant_config
        self.model = DSparkMultiTokenPredictor(
            vllm_config=vllm_config, prefix=maybe_prefix(prefix, "model")
        )

    def embed_input_ids(self, input_ids: torch.Tensor) -> torch.Tensor:
        return self.model.embed_input_ids(input_ids)

    def combine_hidden_states(self, target_hidden_states: torch.Tensor) -> torch.Tensor:
        return self.model.combine_hidden_states(target_hidden_states)

    def forward(
        self,
        input_ids: torch.Tensor | None,
        positions: torch.Tensor,
        hidden_states: torch.Tensor,
        intermediate_tensors: IntermediateTensors | None = None,
        inputs_embeds: torch.Tensor | None = None,
        spec_step_idx: int = 0,
    ) -> torch.Tensor:
        return self.model(
            input_ids, positions, hidden_states, inputs_embeds, spec_step_idx
        )

    def compute_logits(
        self,
        hidden_states: torch.Tensor,
        spec_step_idx: int = 0,
    ) -> torch.Tensor | None:
        return self.model.compute_logits(hidden_states, spec_step_idx)

    def load_weights(self, weights: Iterable[tuple[str, torch.Tensor]]) -> set[str]:
        WEIGHT_NAME_REMAPPING: dict[str, str] = {
            ".emb.tok_emb.weight": ".embed_tokens.weight",
            ".head.weight": ".shared_head.head.weight",
            ".norm.weight": ".shared_head.norm.weight",
        }

        def _remap_weight_name(name: str) -> str:
            for old_pattern, new_pattern in WEIGHT_NAME_REMAPPING.items():
                # Guard: don't rewrite main_norm / attn_norm / ffn_norm / kv_norm /
                # q_norm / compressor.norm which contain "norm.weight" but not
                # the top-level ".norm.weight".
                if old_pattern == ".norm.weight" and (
                    "main_norm" in name
                    or "attn_norm" in name
                    or "ffn_norm" in name
                    or "kv_norm" in name
                    or "q_norm" in name
                    or "compressor.norm" in name
                ):
                    continue
                if old_pattern in name:
                    name = name.replace(old_pattern, new_pattern)
            return name

        stacked_params_mapping = [
            ("gate_up_proj", "w1", 0),
            ("gate_up_proj", "w3", 1),
            ("attn.fused_wqa_wkv", "attn.wq_a", 0),
            ("attn.fused_wqa_wkv", "attn.wkv", 1),
        ]
        params_dict = dict(self.named_parameters())
        loaded_params: set[str] = set()

        tp_size = get_tensor_model_parallel_world_size()
        tp_rank = get_tensor_model_parallel_rank()
        n_head = self.config.num_attention_heads
        n_local_head = n_head // tp_size
        head_rank_start = n_local_head * tp_rank
        head_rank_end = n_local_head * (tp_rank + 1)

        expert_mapping = fused_moe_make_expert_params_mapping(
            self,
            ckpt_gate_proj_name="w1",
            ckpt_down_proj_name="w2",
            ckpt_up_proj_name="w3",
            num_experts=self.config.n_routed_experts,
        )
        expert_scale_suffix = (
            ".weight_scale"
            if getattr(self.config, "expert_dtype", "fp4") == "fp4"
            else ".weight_scale_inv"
        )

        base = self.model.mtp_start_layer_idx  # = num_hidden_layers (43)
        for name, loaded_weight in weights:
            if not name.startswith("mtp."):
                continue
            _p = name.split(".", 2)
            if len(_p) < 3:
                continue
            try:
                stage = int(_p[1])
            except ValueError:
                continue
            rest = _p[2]
            # DSpark MTP = 3 sequential stages (mtp.0/1/2). Route each stage's
            # decoder block into mtp_blocks.{stage}; main_proj/main_norm (stage 0)
            # and the output heads (stage 2) sit at the layer top level.
            if rest.startswith(
                ("main_proj", "main_norm", "hc_head_", "markov_head", "confidence_head")
            ):
                name = f"model.layers.{base}.{rest}"
            elif rest == "norm.weight":
                # stage-2 top-level norm -> shared_head.norm
                name = f"model.layers.{base}.shared_head.norm.weight"
            else:
                # Block weight. When fewer stages than the 3 checkpoint stages,
                # keep the LAST stages (mtp.2 carries the heads, so its block
                # must be present). slot = stage - (CKPT_STAGES - n_stages).
                _ns = self.model.layers[str(base)].n_stages
                slot = stage - (3 - _ns)
                if slot < 0:
                    continue
                name = f"model.layers.{base}.mtp_blocks.{slot}.{rest}"
            if name.endswith(".scale"):
                suffix = (
                    expert_scale_suffix
                    if _EXPERT_SCALE_RE.search(name)
                    else ".weight_scale_inv"
                )
                name = name.removesuffix(".scale") + suffix
            for param_name, weight_name, shard_id in stacked_params_mapping:
                if ".experts." in name:
                    continue
                # Only decoder-block weights get stacked (fused_wqa_wkv,
                # gate_up_proj). Top-level DSpark params (main_proj, markov_head
                # markov_w1/w2, hc_head, confidence_head) must NOT match "w1" etc.
                if "mtp_blocks" not in name:
                    continue
                if weight_name not in name:
                    continue
                name = name.replace(weight_name, param_name)
                param = params_dict[name]
                weight_loader = param.weight_loader
                weight_loader(param, loaded_weight, shard_id)
                loaded_params.add(name)
                break
            else:
                if ".experts." in name:
                    if (
                        "weight_scale" in name
                        and loaded_weight.dtype == torch.float8_e8m0fnu
                    ):
                        loaded_weight = loaded_weight.view(torch.uint8)
                    for mapping in expert_mapping:
                        param_name, weight_name, expert_id, expert_shard_id = mapping
                        if weight_name not in name:
                            continue
                        name_mapped = name.replace(weight_name, param_name)
                        param = params_dict[name_mapped]
                        weight_loader = typing.cast(
                            Callable[..., bool], param.weight_loader
                        )
                        success = weight_loader(
                            param,
                            loaded_weight,
                            name_mapped,
                            shard_id=expert_shard_id,
                            expert_id=expert_id,
                            return_success=True,
                        )
                        if success:
                            name = name_mapped
                            loaded_params.add(name_mapped)
                            break
                    continue
                elif "attn_sink" in name:
                    narrow_weight = loaded_weight[head_rank_start:head_rank_end]
                    n = narrow_weight.shape[0]
                    params_dict[name][:n].copy_(narrow_weight)
                    loaded_params.add(name)
                    continue
                else:
                    if ".shared_experts.w2" in name:
                        name = name.replace(
                            ".shared_experts.w2", ".shared_experts.down_proj"
                        )
                    if name.endswith(".ffn.gate.bias"):
                        name = name.replace(".bias", ".e_score_correction_bias")
                    if name not in params_dict:
                        logger.warning_once("DSpark MTP: unmapped weight %s", name)
                        continue
                    param = params_dict[name]
                    weight_loader = getattr(
                        param, "weight_loader", default_weight_loader
                    )
                    weight_loader(param, loaded_weight)
                    loaded_params.add(name)
                    continue

        # Diagnostic: report critically-missing params (embed_tokens and
        # shared_head.head are legitimately tied to the target model).
        _all = set(params_dict.keys())
        _missing = sorted(_all - loaded_params)
        _crit = [
            m
            for m in _missing
            if "embed_tokens" not in m and "shared_head.head" not in m
        ]
        logger.info(
            "DSpark MTP loaded=%d total=%d missing=%d critical_missing=%d",
            len(loaded_params), len(_all), len(_missing), len(_crit),
        )
        for _m in _crit[:15]:
            logger.info("DSPARK_MISSING %s", _m)
        return loaded_params
